import { useEffect, useState, useCallback } from "react";
import API from "../services/api";
import UnifiedNavbar from "../components/UnifiedNavbar";

const AVATAR_COLORS = ["blue", "green", "amber", "rose", "purple", "orange", "cyan"];

const ROLE_STYLES = {
  admin:   { pill: "sp-absent",  label: "Admin"   },
  staff:   { pill: "sp-leave",   label: "Staff"   },
  student: { pill: "sp-present", label: "Student" },
};

function getInitials(name = "", email = "") {
  if (name.trim()) {
    return name.trim().split(" ").map(w => w[0]).join("").slice(0, 2).toUpperCase();
  }
  return email.slice(0, 2).toUpperCase();
}

function getColor(id) {
  return AVATAR_COLORS[id % AVATAR_COLORS.length];
}

function UserManagement() {
  const [users,      setUsers]      = useState([]);
  const [editId,     setEditId]     = useState(null);
  const [name,       setName]       = useState("");
  const [email,      setEmail]      = useState("");
  const [password,   setPassword]   = useState("");
  const [role,       setRole]       = useState("Student");
  const [search,     setSearch]     = useState("");
  const [filterRole, setFilterRole] = useState("all");
  const [sortAsc,    setSortAsc]    = useState(true);
  const [message,    setMessage]    = useState({ text: "", type: "" });
  const [showForm,   setShowForm]   = useState(false);
  const [showPass,   setShowPass]   = useState(false);
  const [loading,    setLoading]    = useState(false);

  /* ── Fetch all users ──
     Backend: GET api/User                                                   */
  const fetchUsers = useCallback(async () => {
    try {
      const res = await API.get("/User");
      setUsers(res.data);
    } catch (error) {
      console.error("fetchUsers error:", error);
      showMsg("Failed to load users.", "error");
    }
  }, []);

  useEffect(() => {
    fetchUsers();
  }, [fetchUsers]);

  const showMsg = (text, type = "success") => {
    setMessage({ text, type });
    setTimeout(() => setMessage({ text: "", type: "" }), 3500);
  };

  /* ── Open edit form ── */
  const editUser = (user) => {
    setEditId(user.id);
    setName(user.name || "");
    setEmail(user.email);
    setPassword(user.pass);          // never pre-fill password
    setRole(user.role);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  /* ── Save updated user ──
     Backend: PUT api/User/{id}
     C# model expects PascalCase: { Email, Password, Role }                  */
  const updateUser = async () => {
    if (!name.trim()) {
      showMsg("Name cannot be empty.", "error");
      return;
    }
    if (!email.trim()) {
      showMsg("Email cannot be empty.", "error");
      return;
    }
    if (!password.trim()) {
      showMsg("Please enter a new password.", "error");
      return;
    }

    try {
      setLoading(true);
      console.log("PUT /User/" + editId, { Email: email, Password: password, Role: role });

      // Include all fields — C# User model requires Id, Name, Email, Password, Role
      await API.put(`/User/${editId}`, {
        Id:       editId,
        Name:     name,
        Email:    email,
        Password: password,
        Role:     role,
      });

      showMsg("User updated successfully.");
      cancelEdit();
      fetchUsers();
    } catch (error) {
      console.error("updateUser error:", error?.response?.status, error?.response?.data);
      const msg =
        error?.response?.data?.message ||
        error?.response?.data?.title   ||
        `Update failed (${error?.response?.status || "no response"}).`;
      showMsg(msg, "error");
    } finally {
      setLoading(false);
    }
  };

  /* ── Delete user ──
     Backend: DELETE api/User/{id}                                           */
  const deleteUser = async (id) => {
    if (!window.confirm("Are you sure you want to delete this user?")) return;

    try {
      setLoading(true);
      console.log("DELETE /User/" + id);

      await API.delete(`/User/${id}`);

      showMsg("User deleted successfully.");
      fetchUsers();
    } catch (error) {
      console.error("deleteUser error:", error?.response?.status, error?.response?.data);
      const msg =
        error?.response?.data?.message ||
        error?.response?.data?.title   ||
        `Delete failed (${error?.response?.status || "no response"}).`;
      showMsg(msg, "error");
    } finally {
      setLoading(false);
    }
  };

  /* ── Cancel edit ── */
  const cancelEdit = () => {
    setEditId(null);
    setName("");
    setEmail("");
    setPassword("");
    setRole("Student");
    setShowForm(false);
    setShowPass(false);
  };

  /* ── Filtered + sorted list ── */
  const filtered = users
    .filter((u) => {
      const matchSearch =
        u.name?.toLowerCase().includes(search.toLowerCase())  ||
        u.email?.toLowerCase().includes(search.toLowerCase()) ||
        u.role?.toLowerCase().includes(search.toLowerCase());
      const matchRole =
        filterRole === "all" || u.role?.toLowerCase() === filterRole;
      return matchSearch && matchRole;
    })
    .sort((a, b) =>
      sortAsc
        ? a.email?.localeCompare(b.email)
        : b.email?.localeCompare(a.email)
    );

  return (
    <div className="dashboard">
      <UnifiedNavbar />

      <div className="main-content">

        {/* ── Message banner ── */}
        {message.text && (
          <div
            className={`message ${message.type}`}
            style={{ marginBottom: "var(--space-5)", animation: "fadeIn 0.2s ease" }}
          >
            {message.text}
          </div>
        )}

        {/* ── Edit form ── */}
        {showForm && editId && (
          <div
            className="student-form"
            style={{ marginBottom: "var(--space-8)", animation: "slideInUp 0.3s ease" }}
          >
            {/* Name */}
            <input
              type="text"
              placeholder="Full name"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />

            {/* Email */}
            <input
              type="email"
              placeholder="Email address"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />

            {/* Password with show/hide toggle */}
            <div style={{ position: "relative", flex: 1, minWidth: "180px" }}>
              <input
                type={showPass ? "text" : "password"}
                placeholder="New password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                style={{ width: "100%", paddingRight: "40px", marginBottom: 0 }}
              />
              <button
                type="button"
                onClick={() => setShowPass(!showPass)}
                tabIndex={-1}
                style={{
                  position:   "absolute",
                  right:      "10px",
                  top:        "50%",
                  transform:  "translateY(-50%)",
                  background: "none",
                  border:     "none",
                  cursor:     "pointer",
                  color:      "var(--color-text-tertiary)",
                  padding:    "4px",
                  lineHeight: 1,
                }}
              >
                {showPass ? (
                  <svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M3 3l14 14M10.478 10.478A3 3 0 016.52 6.52M8.05 4.2A9.3 9.3 0 0110 4c4 0 7 3.6 8 6-.4 1-1 2.1-1.9 3M2 10c.6-1.3 1.5-2.6 2.7-3.7"/>
                  </svg>
                ) : (
                  <svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M2 10s3-6 8-6 8 6 8 6-3 6-8 6-8-6-8-6z"/>
                    <circle cx="10" cy="10" r="2.5"/>
                  </svg>
                )}
              </button>
            </div>

            {/* Role selector */}
            <select
              value={role}
              onChange={(e) => setRole(e.target.value)}
              style={{
                flex:         1,
                minWidth:     "160px",
                padding:      "var(--space-3) var(--space-4)",
                borderRadius: "var(--radius-md)",
                border:       "1.5px solid var(--color-border)",
                background:   "var(--color-neutral-50)",
                fontSize:     "var(--text-sm)",
                color:        "var(--color-text-primary)",
                outline:      "none",
              }}
            >
              <option value="Admin">Admin</option>
              <option value="Staff">Staff</option>
              <option value="Student">Student</option>
            </select>

            {/* Save button */}
            <button onClick={updateUser} disabled={loading}>
              {loading ? "Saving…" : "Save Changes"}
            </button>

            {/* Cancel button */}
            <button
              onClick={cancelEdit}
              disabled={loading}
              style={{
                background:   "none",
                border:       "1.5px solid var(--color-border)",
                color:        "var(--color-text-secondary)",
                padding:      "var(--space-3) var(--space-6)",
                borderRadius: "var(--radius-md)",
                cursor:       "pointer",
                fontWeight:   "var(--font-semibold)",
                fontSize:     "var(--text-sm)",
              }}
            >
              Cancel
            </button>
          </div>
        )}

        {/* ── Toolbar ── */}
        <div className="grid-toolbar">
          <h2 className="grid-toolbar-title">
            Users
            <span className="grid-count-badge">{filtered.length}</span>
          </h2>

          <div className="grid-search-wrap">
            <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
              <circle cx="6.5" cy="6.5" r="4.5" />
              <path d="M10 10l3.5 3.5" strokeLinecap="round" />
            </svg>
            <input
              className="grid-search"
              type="text"
              placeholder="Search users…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="grid-filter-tabs">
            {["all", "admin", "staff", "student"].map((f) => (
              <button
                key={f}
                className={`grid-filter-btn ${filterRole === f ? "active" : ""}`}
                onClick={() => setFilterRole(f)}
              >
                {f.charAt(0).toUpperCase() + f.slice(1)}
              </button>
            ))}
          </div>

          <button className="grid-sort-btn" onClick={() => setSortAsc(!sortAsc)}>
            <svg viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round">
              <path d="M1 3h10M3 6h6M5 9h2" />
            </svg>
            {sortAsc ? "A–Z" : "Z–A"}
          </button>
        </div>

        {/* ── Grid ── */}
        {filtered.length === 0 ? (
          <div className="person-grid">
            <div className="person-grid-empty">No users found.</div>
          </div>
        ) : (
          <div className="person-grid">
            {filtered.map((u) => {
              const color     = getColor(u.id);
              const roleKey   = u.role?.toLowerCase();
              const roleStyle = ROLE_STYLES[roleKey] || { pill: "sp-unmarked", label: u.role };
              const isEditing = editId === u.id;

              return (
                <div
                  className="person-card"
                  key={u.id}
                  style={{
                    outline:       isEditing ? "2px solid var(--color-brand-primary)" : "none",
                    outlineOffset: "2px",
                  }}
                >
                  <div className={`person-card-bar bar-${color}`} />

                  <div className={`person-avatar av-${color}`}>
                    {getInitials(u.name, u.email)}
                  </div>

                  <div className="person-card-name">{u.name || u.email}</div>
                  <div className="person-card-role">{u.email}</div>

                  <div className="person-card-meta">
                    <div className="person-meta-row">
                      <svg viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.2">
                        <circle cx="7" cy="5" r="2.5" />
                        <path d="M2 12c0-2.76 2.24-5 5-5s5 2.24 5 5" strokeLinecap="round" />
                      </svg>
                      Role: {u.role}
                    </div>
                    <div className="person-meta-row">
                      <svg viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.2">
                        <rect x="2" y="4" width="10" height="7" rx="1" />
                        <path d="M4 4V3a1 1 0 011-1h4a1 1 0 011 1v1" />
                      </svg>
                      ••••••••
                    </div>
                  </div>

                  <div className="person-card-footer">
                    <span className={`person-status-pill ${roleStyle.pill}`}>
                      {isEditing ? "Editing…" : roleStyle.label}
                    </span>
                    <div className="person-card-actions">
                      <button
                        className="person-icon-btn edit-icon"
                        title="Edit user"
                        onClick={() => editUser(u)}
                        disabled={loading}
                      >
                        <svg viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round">
                          <path d="M9.5 2.5l2 2L4 12H2v-2L9.5 2.5z" />
                        </svg>
                      </button>
                      <button
                        className="person-icon-btn delete-icon"
                        title="Delete user"
                        onClick={() => deleteUser(u.id)}
                        disabled={loading}
                      >
                        <svg viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round">
                          <path d="M2 4h10M5 4V2.5h4V4M6 7v4M8 7v4" />
                        </svg>
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

export default UserManagement;
